1	import { provideHttpClient } from '@angular/common/http';
2	import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
3	import { ComponentFixture, TestBed } from '@angular/core/testing';
4	import { Mission } from '../../api';
5	import { MissionList } from './mission-list';
6	
7	const MISSIONS: Mission[] = [
8	  { id: 'm-1', title: 'Calibrate the dish', status: 'open', priority: 1 },
9	  { id: 'm-2', title: 'Rotate the launch codes', status: 'done', priority: 2 },
10	  { id: 'm-3', title: 'Play tic-tac-toe', status: 'open', priority: 3 },
11	];
12	
13	describe('MissionList', () => {
14	  let fixture: ComponentFixture<MissionList>;
15	  let http: HttpTestingController;
16	
17	  beforeEach(async () => {
18	    await TestBed.configureTestingModule({
19	      imports: [MissionList],
20	      providers: [provideHttpClient(), provideHttpClientTesting()],
21	    }).compileComponents();
22	    http = TestBed.inject(HttpTestingController);
23	    fixture = TestBed.createComponent(MissionList);
24	  });
25	
26	  afterEach(() => http.verify());
27	
28	  function respond(missions: Mission[]): void {
29	    http.expectOne('/api/missions').flush(missions);
30	    fixture.detectChanges();
31	  }
32	
33	  it('shows a loading row before the API answers', async () => {
34	    await fixture.whenStable();
35	    const el = fixture.nativeElement as HTMLElement;
36	    expect(el.querySelector('.loading')?.textContent).toContain('Loading');
37	    http.expectOne('/api/missions');
38	  });
39	
40	  it('renders one row per mission', async () => {
41	    await fixture.whenStable();
42	    respond(MISSIONS);
43	    const rows = (fixture.nativeElement as HTMLElement).querySelectorAll('li.mission');
44	    expect(rows.length).toBe(3);
45	    expect(rows[1].textContent).toContain('Rotate the launch codes');
46	  });
47	
48	  it('marks done missions', async () => {
49	    await fixture.whenStable();
50	    respond(MISSIONS);
51	    const rows = (fixture.nativeElement as HTMLElement).querySelectorAll('li.mission');
52	    expect(rows[1].classList.contains('done')).toBe(true);
53	    expect(rows[0].classList.contains('done')).toBe(false);
54	  });
55	
56	  it('shows the empty state for an empty log', async () => {
57	    await fixture.whenStable();
58	    respond([]);
59	    expect((fixture.nativeElement as HTMLElement).querySelector('.empty')).not.toBeNull();
60	  });
61	});
